package ru.kstolu.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.animation.DecelerateInterpolator;
import android.widget.*;
import org.json.*;

public class CookingActivity extends Activity {
    private static final int BG=0xfff9faf6,INK=0xff253127,OLIVE=0xff4c6441,MUTED=0xff626d61;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private JSONObject item,recipe;private JSONArray steps;private CookingState state;private LinearLayout root,body;private TextView clock;private Button timerButton;private boolean visible=false,transition=false,completed=false;private float touchX,touchY;
    private int boot(){return android.provider.Settings.Global.getInt(getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0);}
    private SharedPreferences store(){return getSharedPreferences("cooking",MODE_PRIVATE);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);androidx.core.view.WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);new androidx.core.view.WindowInsetsControllerCompat(getWindow(),getWindow().getDecorView()).setAppearanceLightStatusBars(true);
        try{String incoming=getIntent().getStringExtra("item"),old=store().getString("item",null);item=new JSONObject(incoming!=null?incoming:old==null?"{}":old);recipe=item.getJSONObject("recipe");steps=recipe.getJSONArray("steps");if(steps.length()==0)throw new Exception();boolean same=old!=null&&Library.id(new JSONObject(old).getJSONObject("recipe")).equals(Library.id(recipe));state=same?CookingState.restore(new JSONObject(store().getString("state","{}")),boot()):new CookingState();state.index=Math.min(state.index,steps.length());persist();render();}catch(Exception e){Toast.makeText(this,"Не удалось открыть шаги рецепта.",Toast.LENGTH_LONG).show();finish();}}
    @Override protected void onResume(){super.onResume();visible=true;if(state!=null){if(state.expire(SystemClock.elapsedRealtime())){persist();render();}handler.post(tick);}}
    @Override protected void onPause(){visible=false;handler.removeCallbacks(tick);persist();super.onPause();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
    private void persist(){if(completed||state==null||item==null)return;try{state.remaining=state.left(SystemClock.elapsedRealtime());store().edit().putString("item",item.toString()).putString("state",state.json().toString()).commit();}catch(Exception ignored){}}
    private final Runnable tick=new Runnable(){public void run(){if(!visible||state==null)return;if(state.expire(SystemClock.elapsedRealtime())){persist();render();root.announceForAccessibility("Таймер завершён. Проверьте готовность. Следующий шаг.");}updateClock();handler.postDelayed(this,500);}};
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable bg(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(16));d.setStroke(dp(1),0xffdde3d7);return d;}
    private TextView text(String s,int size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(INK);v.setLineSpacing(dp(5),1);if(bold)v.setTypeface(null,Typeface.BOLD);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(8));body.addView(v,p);return v;}
    private Button button(String s,Runnable action,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(primary?Color.WHITE:OLIVE);b.setBackground(bg(primary?OLIVE:Color.WHITE));b.setMinHeight(dp(48));b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));b.setLayoutParams(p);return b;}
    private void render(){if(isFinishing())return;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(dp(20),dp(12),dp(20),dp(12));setContentView(root);androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars()|androidx.core.view.WindowInsetsCompat.Type.displayCutout());v.setPadding(dp(20)+bars.left,dp(12)+bars.top,dp(20)+bars.right,dp(12)+bars.bottom);return insets;});androidx.core.view.ViewCompat.requestApplyInsets(root);
        Button back=button("‹  К рецепту",this::finish,false);back.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);back.setBackgroundColor(Color.TRANSPARENT);root.addView(back);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(0,dp(8),0,dp(16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(state.index>=steps.length()){text("Вы приготовили блюдо!",28,true);text(recipe.optString("title"),18,false);text("Оцените его — ваша оценка останется в сохранённом.",16,false);RatingBar stars=new RatingBar(this);stars.setNumStars(5);stars.setStepSize(1);stars.setRating(Library.rating(this,recipe));body.addView(stars,new LinearLayout.LayoutParams(-2,-2));text("Перед подачей проверьте готовность. Сигнал таймера сам по себе её не гарантирует.",14,false).setTextColor(MUTED);Button save=button("Сохранить оценку",()->{try{int n=Math.round(stars.getRating());if(n==0){Toast.makeText(this,"Выберите от 1 до 5 звёзд.",Toast.LENGTH_SHORT).show();return;}Library.save(this,item);Library.rate(this,recipe,n);completed=true;store().edit().clear().commit();Toast.makeText(this,"Оценка сохранена. Приятного аппетита!",Toast.LENGTH_LONG).show();finish();}catch(Exception e){Toast.makeText(this,"Не удалось сохранить. Попробуйте ещё раз.",Toast.LENGTH_LONG).show();}},true);body.addView(save);body.addView(button("Вернуться к шагам",()->{state.index=steps.length()-1;persist();render();},false));return;}
        TextView over=text("ШАГ "+(state.index+1)+" ИЗ "+steps.length(),13,true);over.setTextColor(OLIVE);over.setLetterSpacing(.1f);
        ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(steps.length());progress.setProgress(state.index+1);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(OLIVE));body.addView(progress,new LinearLayout.LayoutParams(-1,dp(4)));
        JSONObject step=steps.optJSONObject(state.index);text(step.optString("title"),28,true);text(recipe.optString("title"),14,false).setTextColor(MUTED);
        LinearLayout outer=body,panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),dp(16),dp(20),dp(16));panel.setBackground(bg(Color.WHITE));body.addView(panel,new LinearLayout.LayoutParams(-1,-2));body=panel;text(step.optString("body"),17,false);body=outer;
        if(item.optInt("portions",recipe.optInt("servings",2))!=recipe.optInt("servings",2))text("Шаги описаны для "+recipe.optInt("servings",2)+" порций. Вы выбрали "+item.optInt("portions")+": берите количества из ингредиентов рецепта. Время не умножается на число порций — проверяйте готовность.",14,false).setTextColor(MUTED);
        clock=null;timerButton=null;long preset=step.optLong("timer_seconds",0);
        if(preset>0||state.remaining>0||state.running){
            LinearLayout timerPanel=new LinearLayout(this);timerPanel.setOrientation(LinearLayout.VERTICAL);timerPanel.setPadding(dp(16),dp(8),dp(16),dp(8));timerPanel.setBackground(bg(0xffeaf0e4));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.setMargins(0,dp(16),0,0);body.addView(timerPanel,tp);LinearLayout previous=body;body=timerPanel;
            text("Таймер · до проверки готовности",14,true);LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER_VERTICAL);clock=new TextView(this);clock.setTextSize(28);clock.setTextColor(OLIVE);clock.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);clock.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_NONE);controls.addView(clock,new LinearLayout.LayoutParams(0,dp(56),1));clock.setGravity(Gravity.CENTER_VERTICAL);
            timerButton=button("▷",()->{if(state.running)state.pause(SystemClock.elapsedRealtime());else{long seconds=state.remaining>0?(state.remaining+999)/1000:preset;if(seconds==0){editTimer();return;}state.start(seconds,SystemClock.elapsedRealtime(),boot());}persist();updateClock();},true);controls.addView(timerButton,new LinearLayout.LayoutParams(dp(48),dp(48)));Button edit=button("⋯",this::editTimer,false);edit.setTextSize(24);edit.setContentDescription("Изменить или сбросить таймер");LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(dp(48),dp(48));ep.setMargins(dp(8),0,0,0);controls.addView(edit,ep);body.addView(controls);String hint=step.optString("timer_hint",preset>0?"Запустите, когда начнётся этот этап.":"Время задано вами.");text(hint,14,false).setTextColor(MUTED);body=previous;
            text("Когда время истечёт, откроется следующий шаг. Проверьте готовность еды.",14,false).setTextColor(MUTED);
        }else {Button add=button("＋ Добавить таймер",this::editTimer,false);body.addView(add);}
        LinearLayout nav=new LinearLayout(this);Button prev=button("‹ Назад",()->move(-1),false);prev.setEnabled(state.index>0);nav.addView(prev,new LinearLayout.LayoutParams(0,-2,1));Button next=button(state.index==steps.length()-1?"Готово  ✓":"Далее  ›",()->move(1),true);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);np.setMargins(dp(8),0,0,0);nav.addView(next,np);root.addView(nav);updateClock();
    }
    private void updateClock(){if(clock==null||state.index>=steps.length())return;long sec=state.running||state.remaining>0?(state.left(SystemClock.elapsedRealtime())+999)/1000:steps.optJSONObject(state.index).optLong("timer_seconds",0);clock.setText(String.format(java.util.Locale.ROOT,"%02d:%02d",sec/60,sec%60));timerButton.setText(state.running?"Ⅱ":"▷");timerButton.setContentDescription(state.running?"Пауза таймера":state.remaining>0?"Продолжить таймер":"Запустить таймер");}
    private void editTimer(){if(state.running){state.pause(SystemClock.elapsedRealtime());persist();updateClock();}EditText input=new EditText(this);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);input.setKeyListener(android.text.method.DigitsKeyListener.getInstance("0123456789.,"));input.setRawInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);input.setHint("Минуты, например 8,5");long sec=state.remaining>0?(state.remaining+999)/1000:steps.optJSONObject(state.index).optLong("timer_seconds",0);if(sec>0)input.setText(String.format(java.util.Locale.ROOT,"%.2f",sec/60d));AlertDialog d=new AlertDialog.Builder(this).setTitle("Таймер в минутах").setMessage("В фоне отсчёт сохраняется. Звуковое уведомление при закрытом приложении не гарантируется. После перезагрузки телефона таймер останется на паузе.").setView(input).setNeutralButton("Сбросить",(dialog,w)->{state.running=false;state.remaining=0;state.deadline=0;persist();render();}).setNegativeButton("Отмена",null).setPositiveButton("Установить",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{double min=PriceBook.decimal(input.getText().toString());if(!Double.isFinite(min)||min<1d/60||min>360){input.setError("От 1 секунды до 360 минут");return;}state.running=false;state.deadline=0;state.remaining=Math.round(min*60)*1000;persist();render();d.dismiss();}));d.show();}
    private void move(int delta){if(transition)return;int next=Math.max(0,Math.min(steps.length(),state.index+delta));if(next==state.index)return;Runnable go=()->{state.running=false;state.remaining=0;state.deadline=0;state.index=next;persist();if(android.animation.ValueAnimator.areAnimatorsEnabled()){transition=true;body.animate().translationX(dp(delta>0?-24:24)).alpha(0).setDuration(110).withEndAction(()->{render();body.setTranslationX(dp(delta>0?24:-24));body.setAlpha(0);body.animate().translationX(0).alpha(1).setDuration(170).setInterpolator(new DecelerateInterpolator()).start();transition=false;}).start();}else render();};if(state.running||state.remaining>0)new AlertDialog.Builder(this).setTitle("Перейти к другому шагу?").setMessage("Таймер текущего шага будет остановлен.").setNegativeButton("Остаться",null).setPositiveButton("Перейти",(d,w)->go.run()).show();else go.run();}
    @Override public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){touchX=e.getX();touchY=e.getY();}else if(e.getActionMasked()==MotionEvent.ACTION_UP&&state!=null&&state.index<steps.length()){float dx=e.getX()-touchX,dy=e.getY()-touchY;if(Math.abs(dx)>dp(85)&&Math.abs(dx)>Math.abs(dy)*1.8){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();move(dx<0?1:-1);return true;}}return super.dispatchTouchEvent(e);}
}
